// utils/version-check.js
import { MessageBox } from 'element-ui'

/** 同一版本只提示一次的会话级标记前缀 */
const PROMPT_FLAG_PREFIX = 'version-update-prompted:'
/** 版本检查最小间隔（毫秒）：避免每次路由跳转都请求一次 version.json */
const CHECK_MIN_INTERVAL = 30000

class VersionChecker {
  constructor(options = {}) {
    this.versionUrl = options.versionUrl || `${import.meta.env.BASE_URL}version.json`
    this.currentVersion = null
    this.onUpdate = options.onUpdate || this.defaultUpdateHandler
    /** 上次检查时间，用于节流 */
    this.lastCheckAt = 0
    /** 提示框是否正在显示，避免并发弹窗 */
    this.prompting = false
  }

  async init() {
    // 首次获取当前版本
    this.currentVersion = await this.fetchVersion()

    // 页面可见性变化时立即检测
    document.addEventListener('visibilitychange', () => {
      if (document.visibilityState === 'visible') {
        this.checkUpdate()
      }
    })

    // 直接监听URL变化
    window.addEventListener('popstate', () => {
      this.checkUpdate()
    })

    window.addEventListener('hashchange', () => {
      this.checkUpdate()
    })

    // 重写pushState和replaceState以监听编程式导航
    const originalPushState = history.pushState
    const originalReplaceState = history.replaceState

    history.pushState = (...args) => {
      originalPushState.apply(history, args)
      this.checkUpdate()
    }

    history.replaceState = (...args) => {
      originalReplaceState.apply(history, args)
      this.checkUpdate()
    }
  }

  async fetchVersion() {
    try {
      // 加时间戳防止缓存
      const url = new URL(this.versionUrl, window.location.href)
      const res = await fetch(`${url.href}?t=${Date.now()}`, {
        cache: 'no-cache'
      })
      const data = await res.json()
      return data
    } catch (e) {
      console.error('获取版本信息失败:', e)
      return null
    }
  }

  /**
   * 版本检查（带节流）：
   * 路由跳转/pushState 都会触发，节流后最多 30 秒请求一次 version.json。
   */
  async checkUpdate(force = false) {
    const now = Date.now()
    if (!force && now - this.lastCheckAt < CHECK_MIN_INTERVAL) return
    this.lastCheckAt = now
    const newVersion = await this.fetchVersion()
    if (!newVersion || !this.currentVersion) return

    // 对比版本号或构建时间
    if (newVersion.version !== this.currentVersion.version ||
        newVersion.buildTime !== this.currentVersion.buildTime) {
      console.log('发现新版本:', newVersion)
      this.onUpdate(newVersion)
    }
  }

  /**
   * 默认处理：发现新版本后【提示用户确认】再刷新，不再静默整页 reload。
   * 原因（bug 6285）：发版后未刷新的旧页面，在首次路由跳转（如点「维护」打开预售方案维护页）
   * 时会被静默 location.reload()，表现为整页白屏一闪、已打开的页签与已填写内容全部丢失。
   */
  defaultUpdateHandler(newVersion) {
    this.promptUpdate(newVersion)
  }

  /** 弹确认框：立即刷新 / 稍后再说；同一版本在本次会话内只提示一次 */
  promptUpdate(newVersion) {
    if (this.prompting) return
    const flagKey = `${PROMPT_FLAG_PREFIX}${newVersion.version}-${newVersion.buildTime}`
    try {
      if (sessionStorage.getItem(flagKey)) return
      sessionStorage.setItem(flagKey, '1')
    } catch (e) {
      // sessionStorage 不可用时仍要提示，只是可能重复
    }
    this.prompting = true
    MessageBox.confirm(
      '系统已更新到新版本，刷新后可使用最新功能。刷新会清空当前页面已填写但未保存的内容，请谨慎操作。',
      '系统已更新',
      {
        confirmButtonText: '立即刷新',
        cancelButtonText: '稍后再说',
        type: 'warning',
        closeOnClickModal: false,
        closeOnPressEscape: false,
        showClose: true
      }
    )
      .then(() => {
        this.forceRefresh()
      })
      .catch(() => {
        // 用户选择稍后再说：不刷新，等下次切回页面或下次发版再提示
      })
      .finally(() => {
        this.prompting = false
      })
  }

  forceRefresh() {
    // 清除缓存并刷新
    if ('caches' in window) {
      caches.keys().then(names => {
        names.forEach(name => caches.delete(name))
      })
    }
    window.location.reload()
  }

  destroy() {
  }
}

export default VersionChecker

