/** 部署后旧 HTML 引用的 chunk 404/502 时，提示用户刷新一次拉取最新资源 */
function importWithChunkRetry(importer) {
  return importer().catch((err) => {
    const msg = String(err?.message || err || '')
    const isChunkLoadError =
      (err?.name === 'TypeError' || err?.name === 'ChunkLoadError') &&
      (/Failed to fetch dynamically imported module/i.test(msg) ||
        /Importing a module script failed/i.test(msg) ||
        /error loading dynamically imported module/i.test(msg) ||
        /Loading chunk [\d]+ failed/i.test(msg))
    if (isChunkLoadError && !sessionStorage.getItem(CHUNK_RELOAD_KEY)) {
      sessionStorage.setItem(CHUNK_RELOAD_KEY, '1')
      promptChunkReload()
      return new Promise(() => {})
    }
    sessionStorage.removeItem(CHUNK_RELOAD_KEY)
    throw err
  })
}

/**
 * chunk 加载失败（发版后旧页面引用了已被清理的 chunk）时，先提示再刷新。
 * 不再静默 location.reload()：静默整页刷新表现为「白屏一闪 + 已开页签与已填表单全丢」（bug 6285）。
 */
function promptChunkReload() {
  MessageBox.confirm(
    '页面资源已更新，当前页面无法加载。请刷新页面后重试；刷新会清空当前页面已填写但未保存的内容。',
    '页面需要刷新',
    {
      confirmButtonText: '立即刷新',
      cancelButtonText: '稍后再说',
      type: 'warning',
      closeOnClickModal: false,
      closeOnPressEscape: false,
      showClose: true
    }
  )
    .then(() => {
      window.location.reload()
    })
    .catch(() => {
      // 用户选择稍后再说：页面保持当前状态，可手动刷新恢复
    })
}

