/**
 * bug 6285 验证：发版后旧页面触发版本更新时，不再静默整页刷新，而是弹出确认框。
 * 步骤：加载本地 nginx 站点 → 标记 window.__marker → 改写 dist/version.json 模拟发版
 *      → 等待节流窗口 → 触发一次路由跳转 → 断言弹出「系统已更新」且页面未刷新（marker 仍在）
 */
const fs = require('fs')
const { chromium } = require('playwright')

const VERSION_FILE = 'D:/repository/苏州市房地产监测V3/dist/version.json'
const BASE_URL = 'http://127.0.0.1:8098/'

;(async () => {
  const original = fs.readFileSync(VERSION_FILE, 'utf8')
  const browser = await chromium.launch()
  const page = await browser.newPage()
  page.on('console', (msg) => {
    const text = msg.text()
    if (/新版本|version/i.test(text)) console.log('[console]', text)
  })
  let failed = false
  try {
    await page.goto(BASE_URL, { waitUntil: 'domcontentloaded' })
    await page.waitForTimeout(4000)
    await page.evaluate(() => {
      window.__marker = 'alive'
    })

    // 模拟「服务端已发版」
    const data = JSON.parse(original)
    data.buildTime = '2099/01/01 00:00:00'
    fs.writeFileSync(VERSION_FILE, JSON.stringify(data, null, 2))

    // 版本检查有 30s 节流，等待窗口后再触发路由跳转
    await page.waitForTimeout(31000)
    await page.evaluate(() => {
      history.pushState({}, '', `${location.pathname}${location.search}#/version-check-probe?t=${Date.now()}`)
    })
    await page.waitForTimeout(3000)

    const dialogText = await page.evaluate(() => {
      const el = document.querySelector('.el-message-box')
      return el ? el.innerText.replace(/\s+/g, ' ').trim() : null
    })
    const marker = await page.evaluate(() => window.__marker)
    console.log('弹窗文案:', dialogText)
    console.log('页面未整页刷新(marker 存活):', marker === 'alive')
    failed = !dialogText || !/系统已更新/.test(dialogText) || marker !== 'alive'
  } catch (e) {
    console.error('验证异常:', e)
    failed = true
  } finally {
    fs.writeFileSync(VERSION_FILE, original)
    await browser.close()
  }
  console.log(failed ? '结果: 失败' : '结果: 通过')
  process.exit(failed ? 1 : 0)
})()

