const { chromium } = require('playwright')
;(async () => {
  const browser = await chromium.launch()
  const page = await browser.newPage()
  page.on('console', (m) => console.log('[console:' + m.type() + ']', m.text().slice(0, 200)))
  page.on('pageerror', (e) => console.log('[pageerror]', String(e).slice(0, 200)))
  page.on('requestfailed', (r) => console.log('[reqfail]', r.url().slice(0, 120), r.failure() && r.failure().errorText))
  page.on('response', (r) => {
    if (r.url().includes('version.json')) console.log('[resp]', r.status(), r.url())
  })
  await page.goto('http://127.0.0.1:8098/', { waitUntil: 'domcontentloaded' })
  await page.waitForTimeout(5000)
  const probe = await page.evaluate(async () => {
    let vj = null
    let err = null
    try {
      const res = await fetch('/version.json?t=' + Date.now(), { cache: 'no-cache' })
      vj = await res.json()
    } catch (e) {
      err = String(e)
    }
    return {
      vj,
      err,
      href: location.href,
      pushStatePatched: /checkUpdate/.test(history.pushState.toString()),
      baseUrl: (window.__VUE_APP_ROUTER__ ? 'router-ok' : 'no-router')
    }
  })
  console.log('probe:', JSON.stringify(probe))
  await browser.close()
})()

