const fs = require('fs')
const { chromium } = require('playwright')
const VERSION_FILE = 'D:/repository/苏州市房地产监测V3/dist/version.json'
;(async () => {
  const original = fs.readFileSync(VERSION_FILE, 'utf8')
  const browser = await chromium.launch()
  const page = await browser.newPage()
  page.on('pageerror', (e) => console.log('[pageerror]', String(e).slice(0, 160)))
  await page.route('**/api/**', (route) => route.abort())
  await page.addInitScript(() => {
    window.__mbCalls = []
    const install = () => {
      if (window.ELEMENT && window.ELEMENT.MessageBox && !window.__mbPatched) {
        window.__mbPatched = true
        const orig = window.ELEMENT.MessageBox.confirm
        window.ELEMENT.MessageBox.confirm = function (...args) {
          window.__mbCalls.push({ type: 'confirm', title: args[1] })
          return orig.apply(this, args)
        }
      }
    }
    window.__installMb = install
    setInterval(install, 200)
  })
  await page.goto('http://127.0.0.1:8098/', { waitUntil: 'domcontentloaded' })
  await page.waitForTimeout(4000)
  const data = JSON.parse(original)
  data.buildTime = '2099/01/01 00:00:00'
  fs.writeFileSync(VERSION_FILE, JSON.stringify(data, null, 2))
  await page.waitForTimeout(35000)
  await page.evaluate(() => {
    history.pushState({}, '', `${location.pathname}${location.search}#/probe3?t=${Date.now()}`)
  })
  await page.waitForTimeout(3000)
  const out = await page.evaluate(() => ({
    calls: window.__mbCalls,
    ssKeys: Object.keys(sessionStorage),
    boxes: Array.from(document.querySelectorAll('.el-message-box')).map((e) => e.innerText.replace(/\s+/g, ' ').trim())
  }))
  console.log(JSON.stringify(out, null, 2))
  fs.writeFileSync(VERSION_FILE, original)
  await browser.close()
})()

